">{money(p.price_cents)}</span></div></div></Link><button className="mini" aria-label="Toggle favorite" onClick={async () => { await favoritePrompt({ data: { id: p.id } }); flash(p.favorite ? 'Removed from Favorites' : 'Saved to Favorites') }}>{p.favorite ? 'Saved' : 'Save'}</button></article>)}</section> : <div className="empty">No prompts match these filters.</div>}</main><Dock />{toast && <div className="toast" role="status">{toast}</div>}{preview && <div className="modal" onClick={() => setPreview(null)}><div className="modal-card" onClick={(e) => e.stopPropagation()}><button className="close" onClick={() => setPreview(null)}>×</button><div className="detail"><div className="bigmedia" style={{ '--a': preview.a, '--b': preview.b } as any}><img src={preview.image} alt="" /></div><section className="panel"><p className="mono">{preview.model} / {preview.category}</p><h1>{preview.title}</h1><p>{preview.summary}</p><button className="lime" onClick={async () => { await putCart({ data: { id: preview.id } }); flash('Added to Cart'); setPreview(null) }}>{preview.price_cents ? 'Add to Cart' : 'Get it free'}</button></section></div></div></div>}</div>
